def maximizeSubtreeProduct(n, edges):
    g = [[] for _ in range(n + 1)]
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    parent = [0] * (n + 1)
    order, stack, seen = [], [1], [False] * (n + 1)
    seen[1] = True
    while stack:
        u = stack.pop()
        order.append(u)
        for v in g[u]:
            if not seen[v]:
                seen[v] = True
                parent[v] = u
                stack.append(v)
    f = [None] * (n + 1)
    for u in reversed(order):  # children before parents
        cur = {1: 1}
        for v in g[u]:
            if v == parent[u]:
                continue
            fv = f[v]
            best_v = max(p * k for k, p in fv.items())
            new = {}
            for i, pi in cur.items():
                new[i] = max(new.get(i, 0), pi * best_v)  # cut u-v
                for j, pj in fv.items():  # keep u-v
                    if pi * pj > new.get(i + j, 0):
                        new[i + j] = pi * pj
            cur = new
            f[v] = None
        f[u] = cur
    return max(p * k for k, p in f[1].items())
